#!/usr/bin/env bash
# GENERATED by bench/core/gen_campaign.py — campaign 'vllm-redhat-sly191-depth'. Resumable: rerun to continue
# after an interruption (per-probe markers in <campaign>/tmp/done/). Edit the spec and
# regenerate. Behaviour baked in (no hand-editing needed):
#   * CONTINUE-ON-FAILURE: a server that fails to start is recorded and the run moves on.
#   * PRE-FLIGHT VRAM GUARD: a server whose predicted VRAM > VRAM_BUDGET_MIB is SKIPPED
#     before launch → GPU/VRAM-only, never spills to system RAM (no GTT thrash / freeze).
#   * SUBSET / SHORT runs: ONLY='glob,..' picks probes; REPS=/MAX_TOKENS= shorten a pass.
#   * TWO ROOTS: raw (per-probe run dirs, GPU CSVs, done/ markers) -> <campaign>/tmp/; results
#     (results.jsonl, meta/failures/skipped, server-<name>.txt, charts, appendix) -> <campaign>/results/.
#
# NOTE: rerun of campaigns/perf/2026-10-30-0742-vllm-redhat-sly-depth (Sly 1.8.1) on Sly 1.9.1: image = the sly-redhat profile default since the 2026-10-30 switch (ghcr.io/slybase/vllm-sly-radiance:1.9.1-rocm10.1; gen_campaign.py has no image field -- logged on each server's start line in campaigns/perf/2026-10-30-1932-vllm-redhat-sly191-depth/tmp/2026-10-30-sly191-depth-reruns.log); RADIANCE_CACTUS_DELTA 0.5 as before + 1.9.x fade 4096->16384 / cap 0.5 (code defaults); same probes, ctx, reps
# NOTE: short perf test: cold prefill (unique prompts) + decode at 3 depths; ctx 110000 (prompt+256 fits)
# NOTE: one warm-up on the first shape (Triton JIT bias)
set -uo pipefail
HERE="$(cd "$(dirname "$(readlink -f "${BASH_SOURCE[0]}")")" && pwd)"
ROOT="${ROOT:-$(git -C "$HERE" rev-parse --show-toplevel 2>/dev/null)}"
[ -n "$ROOT" ] || { echo "run.sh: cannot find the repo root (git toplevel of $HERE) -- set ROOT=" >&2; exit 1; }
CAMPAIGN_DIR="${CAMPAIGN_DIR:-$HERE}"
mkdir -p "$CAMPAIGN_DIR" && CAMPAIGN_DIR="$(cd "$CAMPAIGN_DIR" && pwd)"
RAW="$CAMPAIGN_DIR/tmp"; RES="$CAMPAIGN_DIR/results"   # raw (ignored) / results (committed)
mkdir -p "$RAW" "$RES"
EB="$ROOT/bench/perf/engine-bench"
GEN="$ROOT/bench/workloads/tmp"
export MODEL='/mnt/Lin1/work/vllm/sly-radiance/models/RedHatAI__Qwen3.8-27B-MXFP4@16a86728'
export ENGINES_LIST="vllm-sly-redhat-redhat-mxfp4|http://localhost:8000/v1|qwen38-27b-redhat-mxfp4-sly"
# --- run-time knobs (override on the command line) ---
VRAM_BUDGET_MIB="${VRAM_BUDGET_MIB:-32400}"  # guard: skip servers predicted above this
ONLY="${ONLY:-}"                 # comma-separated slug globs; empty = all probes
REPS_OVERRIDE="${REPS:-}"        # override every probe's reps (quick pass)
MAXTOK_OVERRIDE="${MAX_TOKENS:-}"  # override every probe's max_tokens
IMAGE="${IMAGE:-}"  # docker image (spec "image"); empty = the profile's IMAGE
mkdir -p "$RAW/done"
if [ ! -f "$RES/meta.txt" ]; then
  { echo "date=$(date -Iseconds)"; echo "model=$MODEL"; echo "engine=vllm profile=sly-redhat/redhat-mxfp4 served_model=qwen38-27b-redhat-mxfp4-sly"; echo "image=${IMAGE:-profile default}"; echo "vram_budget_mib=$VRAM_BUDGET_MIB"; } > "$RES/meta.txt"
fi

server_needed () {  # any listed probe marker missing?
  local s; for s in "$@"; do [ -f "$RAW/done/$s" ] || return 0; done; return 1; }

want_probe () {  # honor ONLY='glob,glob' filter
  [ -z "$ONLY" ] && return 0
  local g; IFS="," read -ra _globs <<<"$ONLY"
  for g in "${_globs[@]}"; do case "$1" in $g) return 0;; esac; done; return 1; }

probes_selected () {  # 0 if ONLY matches >=1 of this server's probes (don't load a model
  local s; for s in "$@"; do want_probe "$s" && return 0; done; return 1; }  # for filtered-out probes

guard_ok () {  # name predicted_mib -> 0 if within budget (or unknown), else record SKIPPED
  local name=$1 pred=$2
  [ "$pred" -lt 0 ] && return 0   # no prediction available (spec has no vram block)
  if [ "$pred" -gt "$VRAM_BUDGET_MIB" ]; then
    echo "SKIPPED (predicted ${pred} MiB > budget ${VRAM_BUDGET_MIB} MiB): $name" \
      | tee -a "$RES/skipped.txt"; return 1; fi
  return 0; }

ensure_fixtures () {  # auto-build any missing prompt fixture from its canonical recipe
  local WL="$ROOT/bench/workloads" name n k
  for name in "$@"; do
    [ -f "$GEN/$name" ] && continue
    echo ">>> building missing fixture: $name"
    case "$name" in
      codereview-*.txt)
        n="${name#codereview-}"; n="${n%.txt}"
        python3 "$WL/build_prompt.py" --task "$WL/tasks/codereview-large.task.md" \
          --src "$WL/corpus/ts-agentic-code-runner" --src "$WL/corpus/py-rich" \
          --target-tokens "$n" --out "$GEN/$name" ;;
      thinking-hard.txt)
        python3 "$WL/build_prompt.py" --task "$WL/tasks/thinking-hard.prompt.txt" \
          --target-tokens 0 --out "$GEN/thinking-hard.txt" ;;
      agentic-*-v*.txt)  # variant set: build the base with enough --variants (writes v1..vK)
        n="${name#agentic-}"; n="${n%%-v*}"; k="${name##*-v}"; k="${k%.txt}"
        python3 "$WL/build_prompt.py" --task "$WL/tasks/agentic-implement.task.md" \
          --src "$WL/corpus/ts-agentic-code-runner" --target-tokens "$n" \
          --variants "$k" --out "$GEN/agentic-$n.txt" ;;
      agentic-*.txt)
        n="${name#agentic-}"; n="${n%.txt}"
        python3 "$WL/build_prompt.py" --task "$WL/tasks/agentic-implement.task.md" \
          --src "$WL/corpus/ts-agentic-code-runner" --target-tokens "$n" --out "$GEN/$name" ;;
      *)
        echo "FIXTURE-UNKNOWN: no build recipe for '$name' — build it by hand (see" \
             "bench/workloads/README.md) and re-run" >&2; exit 1 ;;
    esac
    [ -f "$GEN/$name" ] || { echo "FIXTURE-BUILD-FAILED: $name" >&2; exit 1; }
  done; }

run_probe () {  # slug conc reps max_tokens api prefix prompt_files...
  local slug=$1 conc=$2 reps=$3 maxt=$4 api=$5 prefix=$6; shift 6
  if [ -f "$RAW/done/$slug" ]; then echo "  skip (done): $slug"; return 0; fi
  if ! want_probe "$slug"; then echo "  skip (ONLY filter): $slug"; return 0; fi
  [ -n "$REPS_OVERRIDE" ] && reps="$REPS_OVERRIDE"
  [ -n "$MAXTOK_OVERRIDE" ] && maxt="$MAXTOK_OVERRIDE"
  local files=""; local f; for f in "$@"; do files="$files $GEN/$f"; done
  if CAMPAIGN_DIR="$CAMPAIGN_DIR" PROMPT_FILE="$files" SLUG="$slug" MAX_TOKENS="$maxt" CONCURRENCY="$conc" \
       REPS="$reps" API="$api" PREFIX_MODE="$prefix" SAMPLE_VRAM=1 "$EB/run.sh"; then
    touch "$RAW/done/$slug"   # engine-bench/run.sh appended its rows to $RES/results.jsonl (success only)
  else echo "  FAILED: $slug" | tee -a "$RES/failures.txt"; fi; }

stop_server () { PORT=8000 "$ROOT/stack/serve/vllm/serve_vllm.sh" stop 2>/dev/null || true; }
start_server () {  # name ctx kv -> 0 up, nonzero (recorded) on failure; run CONTINUES
  local name=$1 ctx=$2 kv=$3 mtp=$4 np=$5
  echo ">>> starting $name (ctx=$ctx kv=$kv mtp=$mtp np=$np)"
  # provenance: the resolved image + digest, env and argv of this server (no GPU, no pull)
  PROFILE='sly-redhat/redhat-mxfp4' IMAGE="$IMAGE" MAXLEN="$ctx" MAXSEQS="$np" KV_DTYPE="$kv" PORT=8000 "$ROOT/stack/serve/vllm/serve_vllm.sh" print > "$RES/server-$name.txt" 2>&1
  if PROFILE='sly-redhat/redhat-mxfp4' IMAGE="$IMAGE" MAXLEN="$ctx" MAXSEQS="$np" KV_DTYPE="$kv" PORT=8000 \
       "$ROOT/stack/serve/vllm/serve_vllm.sh" start; then return 0; fi
  echo "SERVER-FAILED (start OOM/other; expected near the ceiling): $name ctx=$ctx kv=$kv" \
    | tee -a "$RES/failures.txt"; stop_server; return 1; }
trap stop_server EXIT

# --- pre-flight: build any missing prompt fixtures before loading a model ---
ensure_fixtures 'codereview-10000.txt' 'codereview-100000.txt' 'codereview-50000.txt'

# ===== server: redhat-sly191-fp8kv-ctx110000 (ctx=110000 np=1 kv=fp8 mtp=0 predicted_vram=-1 MiB) =====
if ! server_needed 'redhat-sly191-cr10000' 'redhat-sly191-cr50000' 'redhat-sly191-cr100000'; then
  echo "  skip (done): redhat-sly191-fp8kv-ctx110000 — all its probes are already complete"
elif ! probes_selected 'redhat-sly191-cr10000' 'redhat-sly191-cr50000' 'redhat-sly191-cr100000'; then
  echo "  skip (ONLY filter): redhat-sly191-fp8kv-ctx110000"
elif guard_ok 'redhat-sly191-fp8kv-ctx110000' -1; then
  if start_server 'redhat-sly191-fp8kv-ctx110000' 110000 'fp8' 0 1; then
    WARMUP=1 run_probe 'redhat-sly191-cr10000' 1 2 256 chat unique 'codereview-10000.txt'
    WARMUP=0 run_probe 'redhat-sly191-cr50000' 1 2 256 chat unique 'codereview-50000.txt'
    WARMUP=0 run_probe 'redhat-sly191-cr100000' 1 2 256 chat unique 'codereview-100000.txt'
    stop_server
  fi
fi

# ===== report (last step): theme-aware SVG charts + appendix.md, embedded in the write-up =====
if [ -f "$RES/results.jsonl" ]; then
  python3 "$ROOT/bench/core/report.py" "$CAMPAIGN_DIR" \
    && echo "charts: $RES/charts/  ·  appendix: $RES/appendix.md"
fi
echo "campaign done. consolidated results: $RES/results.jsonl  (raw: $RAW/)"
[ -f "$RES/skipped.txt" ] && { echo "--- guard-skipped (over budget) ---"; cat "$RES/skipped.txt"; } || true
